// src/modules/catalog/catalog.service.ts
// Serviço de catálogo canônico

import { runQueryWithTenant, runQueriesWithTenant } from '../../core/database/pool';
import type {
  CanonicalProduct,
  LocalProduct,
  CatalogSearchResult,
} from './catalog.types';

interface CanonicalProductRow {
  id: string;
  tenant_id: string;
  gtin: string;
  name: string;
  brand: string | null;
  images: string[];
  attributes: any;
  category_id: string | null;
  type: string;
  created_at: Date;
  updated_at: Date;
}

interface LocalProductRow {
  id: string;
  tenant_id: string;
  merchant_id: string;
  name: string;
  description: string | null;
  images: string[];
  attributes: any;
  category_id: string | null;
  type: string;
  created_at: Date;
  updated_at: Date;
}

class CatalogService {
  /**
   * Converte row do banco para CanonicalProduct
   */
  private toCanonicalProduct(row: CanonicalProductRow): CanonicalProduct {
    return {
      id: row.id,
      tenantId: row.tenant_id,
      gtin: row.gtin,
      name: row.name,
      brand: row.brand || undefined,
      images: row.images || [],
      attributes: row.attributes || {},
      categoryId: row.category_id || '',
      type: 'INDUSTRIAL',
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }

  /**
   * Converte row do banco para LocalProduct
   */
  private toLocalProduct(row: LocalProductRow): LocalProduct {
    return {
      id: row.id,
      tenantId: row.tenant_id,
      merchantId: row.merchant_id,
      name: row.name,
      description: row.description || undefined,
      images: row.images || [],
      attributes: row.attributes || {},
      categoryId: row.category_id || '',
      type: 'LOCAL',
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }

  /**
   * Busca produto canônico por GTIN
   */
  async findByGTIN(tenantId: string, gtin: string): Promise<CanonicalProduct | null> {
    const row = await runQueryWithTenant<CanonicalProductRow>(
      tenantId,
      {
        text: `
          SELECT id, tenant_id, gtin, name, brand, images, attributes, category_id, type, created_at, updated_at
          FROM canonical_products
          WHERE tenant_id = $1 AND gtin = $2
        `,
        values: [tenantId, gtin],
      }
    );

    return row ? this.toCanonicalProduct(row) : null;
  }

  /**
   * Busca produto canônico por ID
   */
  async findById(tenantId: string, productId: string): Promise<CanonicalProduct | null> {
    const row = await runQueryWithTenant<CanonicalProductRow>(
      tenantId,
      {
        text: `
          SELECT id, tenant_id, gtin, name, brand, images, attributes, category_id, type, created_at, updated_at
          FROM canonical_products
          WHERE tenant_id = $1 AND id = $2
        `,
        values: [tenantId, productId],
      }
    );

    return row ? this.toCanonicalProduct(row) : null;
  }

  /**
   * Busca produtos no catálogo (canônicos + locais)
   * ⚠️ Importante: NÃO filtra por domain, taxonomy ou marketplace.
   * Categoria aqui é CANÔNICA.
   */
  async search(
    tenantId: string,
    query: string,
    options?: {
      regionId?: string;
      cityId?: string;
      categoryId?: string;
      type?: 'INDUSTRIAL' | 'LOCAL' | 'ALL';
      limit?: number;
      offset?: number;
    }
  ): Promise<CatalogSearchResult> {
    const {
      categoryId,
      type = 'ALL',
      limit = 50,
      offset = 0,
    } = options || {};

    const searchTerm = `%${query}%`;

    const canonicalProducts: CanonicalProduct[] = [];
    const localProducts: LocalProduct[] = [];

    // Produtos canônicos
    if (type === 'ALL' || type === 'INDUSTRIAL') {
      let canonicalQuery = `
        SELECT id, tenant_id, gtin, name, brand, images, attributes, category_id, type, created_at, updated_at
        FROM canonical_products
        WHERE tenant_id = $1
          AND (name ILIKE $2 OR brand ILIKE $2 OR gtin = $3)
      `;

      const params: any[] = [tenantId, searchTerm, query];

      if (categoryId) {
        canonicalQuery += ` AND category_id = $${params.length + 1}`;
        params.push(categoryId);
      }

      canonicalQuery += `
        ORDER BY name ASC
        LIMIT $${params.length + 1}
        OFFSET $${params.length + 2}
      `;
      params.push(limit, offset);

      const canonicalRows = await runQueriesWithTenant<CanonicalProductRow>(
        tenantId,
        { text: canonicalQuery, values: params }
      );

      canonicalProducts.push(...canonicalRows.map(r => this.toCanonicalProduct(r)));
    }

    // Produtos locais
    if (type === 'ALL' || type === 'LOCAL') {
      let localQuery = `
        SELECT id, tenant_id, merchant_id, name, description, images, attributes, category_id, type, created_at, updated_at
        FROM local_products
        WHERE tenant_id = $1
          AND (name ILIKE $2 OR description ILIKE $2)
      `;

      const params: any[] = [tenantId, searchTerm];

      if (categoryId) {
        localQuery += ` AND category_id = $${params.length + 1}`;
        params.push(categoryId);
      }

      localQuery += `
        ORDER BY name ASC
        LIMIT $${params.length + 1}
        OFFSET $${params.length + 2}
      `;
      params.push(limit, offset);

      const localRows = await runQueriesWithTenant<LocalProductRow>(
        tenantId,
        { text: localQuery, values: params }
      );

      localProducts.push(...localRows.map(r => this.toLocalProduct(r)));
    }

    return {
      canonicalProducts,
      localProducts,
      offers: [],
      total: canonicalProducts.length + localProducts.length,
    };
  }
}

export const catalogService = new CatalogService();
